package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact API67 input and error contracts admitted in Wave43.
func TestRunJSONEOFSourceContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeJsonEOFObserve67.cls"), "@IsTest private class GladeJsonEOFObserve67 {\nprivate static void finish(List<Object> rows,Integer expected){System.assertEquals(expected,rows.size(),'Every supplemental operation retained');String text=JSON.serialize(rows);System.assert(text.length()<2900,'Supplemental observation exceeds bound');verify(rows);}\nprivate static void observe(List<String> inputs){\nList<Object> rows=new List<Object>();\nfor(String input:inputs){\nMap<String,Object> row=new Map<String,Object>{'input'=>input,'utf16Length'=>input.length()};\ntry{Object value=JSON.deserializeUntyped(input);row.put('value',value);row.put('returned',true);}\ncatch(Exception e){row.put('type',e.getTypeName());row.put('message',e.getMessage());}\nrows.add(row);\n}\nfinish(rows,4);\n}\n@IsTest static void objectEOF(){observe(new List<String>{'{\"broken\":','{','{\"a\":','{\"longerName\": '});}\n@IsTest static void arrayAndNestedEOF(){observe(new List<String>{'[','[1,','{\"a\":[','{\"outer\":{\"inner\":'});}\n@IsTest static void whitespaceEOF(){observe(new List<String>{'{\"broken\": ','\\n{\"broken\":\\n','  [1, \\n','{\"a\":{\\n  \"b\":'});}\n\nprivate static void verify(List<Object> rows){\nString first=(String)((Map<String,Object>)rows[0]).get('input');String encoded;\nif(first=='{\"broken\":'){encoded='[{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:1, column:21]\",\"type\":\"System.JSONException\",\"utf16Length\":10,\"input\":\"{\\\\\"broken\\\\\":\"},{\"message\":\"Unexpected end-of-input: expected close marker for OBJECT (from [line:1, column:3]\",\"type\":\"System.JSONException\",\"utf16Length\":1,\"input\":\"{\"},{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:1, column:11]\",\"type\":\"System.JSONException\",\"utf16Length\":5,\"input\":\"{\\\\\"a\\\\\":\"},{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:1, column:31]\",\"type\":\"System.JSONException\",\"utf16Length\":15,\"input\":\"{\\\\\"longerName\\\\\": \"}]';}\nelse if(first=='['){encoded='[{\"message\":\"Unexpected end-of-input: expected close marker for ARRAY (from [line:1, column:3]\",\"type\":\"System.JSONException\",\"utf16Length\":1,\"input\":\"[\"},{\"message\":\"Unexpected end-of-input within/between ARRAY entries at [line:1, column:7]\",\"type\":\"System.JSONException\",\"utf16Length\":3,\"input\":\"[1,\"},{\"message\":\"Unexpected end-of-input: expected close marker for ARRAY (from [line:1, column:13]\",\"type\":\"System.JSONException\",\"utf16Length\":6,\"input\":\"{\\\\\"a\\\\\":[\"},{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:1, column:37]\",\"type\":\"System.JSONException\",\"utf16Length\":18,\"input\":\"{\\\\\"outer\\\\\":{\\\\\"inner\\\\\":\"}]';}\nelse if(first=='{\"broken\": '){encoded='[{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:1, column:23]\",\"type\":\"System.JSONException\",\"utf16Length\":11,\"input\":\"{\\\\\"broken\\\\\": \"},{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:3, column:13]\",\"type\":\"System.JSONException\",\"utf16Length\":12,\"input\":\"\\\\n{\\\\\"broken\\\\\":\\\\n\"},{\"message\":\"Unexpected end-of-input within/between ARRAY entries at [line:2, column:8]\",\"type\":\"System.JSONException\",\"utf16Length\":7,\"input\":\"  [1, \\\\n\"},{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:2, column:20]\",\"type\":\"System.JSONException\",\"utf16Length\":13,\"input\":\"{\\\\\"a\\\\\":{\\\\n  \\\\\"b\\\\\":\"}]';}\nelse{System.assert(false,'Unexpected EOF observation group');return;}\nList<Object> expected=(List<Object>)JSON.deserializeUntyped(encoded);\nSystem.assertEquals(expected.size(),rows.size(),'Exact EOF row population');\nfor(Integer i=0;i<expected.size();i++){\n Map<String,Object> want=(Map<String,Object>)expected[i];Map<String,Object> got=(Map<String,Object>)rows[i];\n System.assertEquals(want.keySet(),got.keySet(),'Exact EOF fields '+i);\n for(String key:want.keySet())System.assertEquals(want.get(key),got.get(key),'Exact EOF value '+i+':'+key);\n}\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeJsonEOFObserve67.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 3 || got.Passed != 3 || got.Failed != 0 || got.Skipped != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact JSON EOF contracts failed: %s", data)
	}
}
